// Espera a que el slider esté listo
setTimeout(() => {
  const swiperEl = wwLib.getFrontDocument().querySelector(".swiper");

  if (swiperEl && swiperEl.swiper) {
    const swiper = swiperEl.swiper;

    // Aumenta el mínimo de px necesarios para activar el swipe
    swiper.params.threshold = 50; // por defecto es 0, sube este valor

    // Exige que el swipe sea más largo para cambiar de slide
    swiper.params.longSwipesRatio = 0.3; // por defecto 0.5, ponlo más bajo
    swiper.params.shortSwipes = false; // desactiva swipes cortos

    swiper.update();
  }
}, 500);

