// Get the current date
const currentDate = new Date();

// Get the current year and month
const year = currentDate.getFullYear();
const month = currentDate.getMonth();

// Get the first day of the month
const firstDayOfMonth = new Date(year, month, 1);
const lastDayOfMonth = new Date(year, month + 1, 0);

// Format dates to 'yyyy-mm-dd'
const formatDate = date => date.toISOString().split('T')[0];

// Get timestamps at 00:00
const getTimestampAtMidnight = date => new Date(date.setHours(0, 0, 0, 0)).getTime();

const result = [
  formatDate(firstDayOfMonth),
  formatDate(lastDayOfMonth),
  getTimestampAtMidnight(firstDayOfMonth),
  getTimestampAtMidnight(lastDayOfMonth)
];

return result;

// Assuming we have access to pluginVariables object and necessary data for start date and deadline comparison
const userActions = pluginVariables['f5856798-485d-47be-b433-d43d771c64e1']['user']?.['user_records']?.['actions'] || [];

// Get today's date in YYYY-MM-DD format
const today = new Date().toISOString().split('T')[0];

// Filter actions based on the required conditions and collect corresponding IDs
const delayedActionIds = userActions.flatMap(action => 
  // Check if the action meets the filtering conditions
  action.valid_record === true &&
  action.approved_record === false &&
  action.pending_approval === false
    ? action._actions.filter(_action => 
        _action.start_date <= today && // Action has started
        _action.deadline < today // Action is delayed
      ).map(_action => action.id)
    : []
);

return delayedActionIds;

